<?php require __DIR__.'/../app/bootstrap.php';$id=(int)($_GET['id']??0);$s=$pdo->prepare("SELECT file_path FROM documents WHERE id=? AND status='published'");$s->execute([$id]);$d=$s->fetch();if(!$d||!$d['file_path'])exit('File tidak tersedia');$pdo->prepare("UPDATE documents SET downloads=downloads+1 WHERE id=?")->execute([$id]);$file=__DIR__.'/'.$d['file_path'];if(!is_file($file))exit('File tidak ditemukan');header('Content-Type: application/pdf');header('Content-Disposition: inline; filename="'.basename($file).'"');readfile($file);